import{Z as e,e as i,f as n,a0 as o}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Drip","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/drip.md","filePath":"integrations/email-marketing/drip.md","lastUpdated":1780377007000}'),a={name:"integrations/email-marketing/drip.md"};function r(s,t,l,c,h,p){return i(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="drip" tabindex="-1">Drip <a class="header-anchor" href="#drip" aria-label="Permalink to &quot;Drip&quot;">​</a></h1><p>Connect Drip to send newsletter sign-ups to your chosen mailing list. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Drip as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-drip-api" tabindex="-1">Step 2. Connect to the Drip API <a class="header-anchor" href="#step-2-connect-to-the-drip-api" aria-label="Permalink to &quot;Step 2. Connect to the Drip API&quot;">​</a></h3><ol><li>Go to <a href="https://www.getdrip.com/user/applications" target="_blank">Drip</a> and login to your account.</li><li>Click on <strong>OAuth Applications</strong>.</li><li>Enter a name for your application, and click the <strong>Create Application</strong> button.</li><li>In the <strong>Callback URL</strong> field, enter the value from the <strong>Redirect URI</strong> field In Formie.</li><li>Copy the <strong>Client ID</strong> from Drip and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from Drip and paste in the <strong>Client Secret</strong> field in Formie.</li><li>Click the <strong>Activate</strong> button.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Drip, where you must approve Formie to access your Drip account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Select the destination list and map its required email field to your form’s Email Address field. Map any additional fields your list requires using the variable picker. If you collect a newsletter opt-in, configure integration conditions so only visitors who choose it are sent.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Look up the test email in the selected list and check its mapped values and subscription state. If the provider requires confirmation, complete that step before expecting an active subscription.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const u=e(a,[["render",r]]);export{g as __pageData,u as default};
